// A conversion between the constructor function and its method runs code
// (Probe's toString) that reads the prototype before the method is stored.
var shapes = {};
class Probe {
  toString() {
    return shapes.Box.prototype.area === undefined ? "no area yet" : "area";
  }
}
var probe = new Probe();
shapes.Box = function (w) {
  this.w = w;
};
var seen = "" + probe;
shapes.Box.prototype.area = function () {
  return this.w * this.w;
};
module.exports = { shapes: shapes, seen: seen };
